-- =============================================================================
-- FoT-AMS  VERIFY the assignment data   (READ-ONLY)
--
--   mysql -u <user> -p faculty_ams -e "source database/verify_assignment_data.sql"
--
-- Part 1 (first result set): the assignment rules as PASS / FAIL / WARN checks
--   population (1 admin, >= 5 lecturers, >= 4 technical officers, >= 20 undergraduates incl. REPEAT and
--   BATCH_MISSED), 15 theory + 15 practical sessions, the five attendance scenarios (> 80 %, exactly 80 %,
--   < 80 % without medical, > 80 % with medical, < 80 % with medical), medical tracking (approved / pending /
--   rejected + reviewer), marks 0-100, CA >= 40 %, attendance + CA eligibility, grades and final marks,
--   SGPA / CGPA.
-- Part 2 (the following result sets): the reports behind the checks - attendance per student and course
--   (theory / practical / combined), eligibility per student and course, SGPA and CGPA per student, and the
--   batch summaries.
--
-- A scenario or population check that says FAIL means the DATA does not (yet) demonstrate that requirement; load
-- the demo data (README) or add real data. Nothing here is invented: the rules are those coded in
-- AcademicRules.java / AttendanceService.java:
--   attendance %  = 100 x (present + late + approved-medical absences) / (15 x number of components)
--   eligible      = CA % >= 40 AND attendance % >= 80
--   overall       = sum(mark / max x weightage) / sum(weightage) x 100
--   GPA           = sum(grade points x credits) / sum(credits)   over PUBLISHED results
-- The grade bands are the application's own and are NOT verified against UGC Commission Circular No. 12-2024.
--
-- Output: ONE result set with the columns  check_name | status | detail
--   PASS  the check found nothing wrong / the requirement is met
--   FAIL  a rule is broken (fix the data or the schema; see README, Recovery)
--   WARN  suspicious or incomplete; needs a human decision
--   INFO  a count or listing, no judgement
--   SKIP  the check was NOT run because a table or column it needs does not exist
-- A missing table or column never stops the script: the dependent checks are reported as SKIP.
--
-- READ-ONLY: only SELECT statements and session variables (@q1, @sql ...). Nothing is created, changed,
-- locked or deleted, no temporary table and no special privilege is needed (SELECT on the schema).
-- It reads the database it is run against; it says nothing about any other copy of the data.
-- =============================================================================

USE faculty_ams;

SET @q1 := 'SELECT ''00 scope'' AS check_name, ''INFO'' AS status, CONVERT(''Read-only check of the assignment data rules (ICT2132 mini project) in the database this script is run against.'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail';
SET @q2 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'users' AND COLUMN_NAME IN ('role', 'is_active')) = 2, 'SELECT ''01 administrators (active)'' AS check_name, IF(x.c >= 1, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' active admin(s) (required: at least 1)'') USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM users WHERE role = ''ADMIN'' AND is_active = 1) AS c) x', 'SELECT ''01 administrators (active)'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: users(role, is_active)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q3 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'users' AND COLUMN_NAME IN ('role', 'is_active')) = 2, 'SELECT ''01 lecturers (active)'' AS check_name, IF(x.c >= 5, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' active lecturer(s) (required: at least 5)'') USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM users WHERE role = ''LECTURER'' AND is_active = 1) AS c) x', 'SELECT ''01 lecturers (active)'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: users(role, is_active)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q4 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'users' AND COLUMN_NAME IN ('role', 'is_active')) = 2, 'SELECT ''01 technical officers (active)'' AS check_name, IF(x.c >= 4, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' active technical officer(s) (required: at least 4)'') USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM users WHERE role = ''TECHNICAL_OFFICER'' AND is_active = 1) AS c) x', 'SELECT ''01 technical officers (active)'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: users(role, is_active)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q5 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'users' AND COLUMN_NAME IN ('role', 'is_active')) = 2, 'SELECT ''01 undergraduates (active)'' AS check_name, IF(x.c >= 20, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' active undergraduate(s) (required: at least 20)'') USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM users WHERE role = ''STUDENT'' AND is_active = 1) AS c) x', 'SELECT ''01 undergraduates (active)'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: users(role, is_active)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q6 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'students' AND COLUMN_NAME IN ('student_status')) = 1, 'SELECT ''01 undergraduates with status REGULAR'' AS check_name, IF(x.c >= 1, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' student(s) (required: at least 1)'') USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM students WHERE student_status = ''REGULAR'') AS c) x', 'SELECT ''01 undergraduates with status REGULAR'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: students(student_status)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q7 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'students' AND COLUMN_NAME IN ('student_status')) = 1, 'SELECT ''01 undergraduates with status REPEAT'' AS check_name, IF(x.c >= 1, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' student(s) (required: at least 1)'') USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM students WHERE student_status = ''REPEAT'') AS c) x', 'SELECT ''01 undergraduates with status REPEAT'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: students(student_status)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q8 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'students' AND COLUMN_NAME IN ('student_status')) = 1, 'SELECT ''01 undergraduates with status BATCH_MISSED'' AS check_name, IF(x.c >= 1, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' student(s) (required: at least 1)'') USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM students WHERE student_status = ''BATCH_MISSED'') AS c) x', 'SELECT ''01 undergraduates with status BATCH_MISSED'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: students(student_status)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q9 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'courses' AND COLUMN_NAME IN ('course_id')) = 1, 'SELECT ''01 courses'' AS check_name, IF(x.c >= 1, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' course(s) (required: at least 1)'') USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM courses) AS c) x', 'SELECT ''01 courses'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: courses(course_id)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q10 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'session_attendance' AND COLUMN_NAME IN ('user_id', 'component_id', 'session_no')) = 3, 'SELECT ''02 student/component groups that do NOT have exactly sessions 1..15'' AS check_name, IF(x.c = 0, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' group(s)'', IFNULL(CONCAT('' (e.g. '', x.s, '')''), '''')) USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM (SELECT user_id, component_id FROM session_attendance GROUP BY user_id, component_id HAVING COUNT(DISTINCT session_no) <> 15 OR MIN(session_no) <> 1 OR MAX(session_no) <> 15) g) AS c, (SELECT SUBSTRING(GROUP_CONCAT(DISTINCT CONCAT(g.user_id, ''/'', g.component_id) SEPARATOR '', ''), 1, 200) FROM (SELECT user_id, component_id FROM session_attendance GROUP BY user_id, component_id HAVING COUNT(DISTINCT session_no) <> 15 OR MIN(session_no) <> 1 OR MAX(session_no) <> 15) g) AS s) x', 'SELECT ''02 student/component groups that do NOT have exactly sessions 1..15'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: session_attendance(user_id, component_id, session_no)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q11 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'course_component' AND COLUMN_NAME IN ('component_id', 'type')) = 2 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'session_attendance' AND COLUMN_NAME IN ('user_id', 'component_id', 'session_no')) = 3, 'SELECT ''02 THEORY components that have 15 sessions for every recorded student (need at least one)'' AS check_name, IF(x.c > 0, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' component(s)'', IFNULL(CONCAT('' (e.g. '', x.s, '')''), '''')) USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM course_component cc WHERE cc.type = ''THEORY'' AND EXISTS (SELECT 1 FROM session_attendance a WHERE a.component_id = cc.component_id) AND NOT EXISTS (SELECT 1 FROM session_attendance a2 WHERE a2.component_id = cc.component_id GROUP BY a2.user_id HAVING COUNT(DISTINCT a2.session_no) <> 15)) AS c, (SELECT SUBSTRING(GROUP_CONCAT(DISTINCT cc.component_id SEPARATOR '', ''), 1, 200) FROM course_component cc WHERE cc.type = ''THEORY'' AND EXISTS (SELECT 1 FROM session_attendance a WHERE a.component_id = cc.component_id) AND NOT EXISTS (SELECT 1 FROM session_attendance a2 WHERE a2.component_id = cc.component_id GROUP BY a2.user_id HAVING COUNT(DISTINCT a2.session_no) <> 15)) AS s) x', 'SELECT ''02 THEORY components that have 15 sessions for every recorded student (need at least one)'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: course_component(component_id, type), session_attendance(user_id, component_id, session_no)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q12 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'course_component' AND COLUMN_NAME IN ('component_id', 'type')) = 2 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'session_attendance' AND COLUMN_NAME IN ('user_id', 'component_id', 'session_no')) = 3, 'SELECT ''02 PRACTICAL components that have 15 sessions for every recorded student (need at least one)'' AS check_name, IF(x.c > 0, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' component(s)'', IFNULL(CONCAT('' (e.g. '', x.s, '')''), '''')) USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM course_component cc WHERE cc.type = ''PRACTICAL'' AND EXISTS (SELECT 1 FROM session_attendance a WHERE a.component_id = cc.component_id) AND NOT EXISTS (SELECT 1 FROM session_attendance a2 WHERE a2.component_id = cc.component_id GROUP BY a2.user_id HAVING COUNT(DISTINCT a2.session_no) <> 15)) AS c, (SELECT SUBSTRING(GROUP_CONCAT(DISTINCT cc.component_id SEPARATOR '', ''), 1, 200) FROM course_component cc WHERE cc.type = ''PRACTICAL'' AND EXISTS (SELECT 1 FROM session_attendance a WHERE a.component_id = cc.component_id) AND NOT EXISTS (SELECT 1 FROM session_attendance a2 WHERE a2.component_id = cc.component_id GROUP BY a2.user_id HAVING COUNT(DISTINCT a2.session_no) <> 15)) AS s) x', 'SELECT ''02 PRACTICAL components that have 15 sessions for every recorded student (need at least one)'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: course_component(component_id, type), session_attendance(user_id, component_id, session_no)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q13 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'course_component' AND COLUMN_NAME IN ('component_id', 'course_id', 'type')) = 3 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'session_attendance' AND COLUMN_NAME IN ('component_id')) = 1 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'courses' AND COLUMN_NAME IN ('course_id', 'course_code')) = 2, 'SELECT ''02 courses with both a THEORY and a PRACTICAL component holding attendance'' AS check_name, IF(x.c > 0, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' course(s)'', IFNULL(CONCAT('' (e.g. '', x.s, '')''), '''')) USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM courses c WHERE EXISTS (SELECT 1 FROM course_component t JOIN session_attendance a ON a.component_id = t.component_id WHERE t.course_id = c.course_id AND t.type = ''THEORY'') AND EXISTS (SELECT 1 FROM course_component p JOIN session_attendance a2 ON a2.component_id = p.component_id WHERE p.course_id = c.course_id AND p.type = ''PRACTICAL'')) AS c, (SELECT SUBSTRING(GROUP_CONCAT(DISTINCT c.course_code SEPARATOR '', ''), 1, 200) FROM courses c WHERE EXISTS (SELECT 1 FROM course_component t JOIN session_attendance a ON a.component_id = t.component_id WHERE t.course_id = c.course_id AND t.type = ''THEORY'') AND EXISTS (SELECT 1 FROM course_component p JOIN session_attendance a2 ON a2.component_id = p.component_id WHERE p.course_id = c.course_id AND p.type = ''PRACTICAL'')) AS s) x', 'SELECT ''02 courses with both a THEORY and a PRACTICAL component holding attendance'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: course_component(component_id, course_id, type), session_attendance(component_id), courses(course_id, course_code)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q14 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'session_attendance' AND COLUMN_NAME IN ('attendance_id', 'user_id', 'component_id', 'status')) = 4 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'course_component' AND COLUMN_NAME IN ('component_id', 'course_id', 'type')) = 3 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'medical' AND COLUMN_NAME IN ('medical_id', 'attendance_id', 'approval_status')) = 3 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'users' AND COLUMN_NAME IN ('user_id', 'username')) = 2, 'SELECT ''03 scenario 1: attendance above 80 % without needing a medical'' AS check_name, IF(x.c > 0, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' student/course(s)'', IFNULL(CONCAT('' (e.g. '', x.s, '')''), '''')) USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM (SELECT sa.user_id, cc.course_id, COUNT(DISTINCT cc.component_id) AS comps,
        SUM(sa.status IN (''present'', ''late'')) AS pres,
        SUM(sa.status = ''absent'' AND md.approval_status = ''approved'') AS med_ok,
        SUM(md.medical_id IS NOT NULL) AS med_any
 FROM session_attendance sa
 JOIN course_component cc ON cc.component_id = sa.component_id
 LEFT JOIN medical md ON md.attendance_id = sa.attendance_id
 GROUP BY sa.user_id, cc.course_id) a JOIN users u ON u.user_id = a.user_id WHERE 100 * a.pres > 80 * (15 * a.comps)) AS c, (SELECT SUBSTRING(GROUP_CONCAT(DISTINCT CONCAT(u.username, '' '', a.course_id) SEPARATOR '', ''), 1, 200) FROM (SELECT sa.user_id, cc.course_id, COUNT(DISTINCT cc.component_id) AS comps,
        SUM(sa.status IN (''present'', ''late'')) AS pres,
        SUM(sa.status = ''absent'' AND md.approval_status = ''approved'') AS med_ok,
        SUM(md.medical_id IS NOT NULL) AS med_any
 FROM session_attendance sa
 JOIN course_component cc ON cc.component_id = sa.component_id
 LEFT JOIN medical md ON md.attendance_id = sa.attendance_id
 GROUP BY sa.user_id, cc.course_id) a JOIN users u ON u.user_id = a.user_id WHERE 100 * a.pres > 80 * (15 * a.comps)) AS s) x', 'SELECT ''03 scenario 1: attendance above 80 % without needing a medical'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: session_attendance(attendance_id, user_id, component_id, status), course_component(component_id, course_id, type), medical(medical_id, attendance_id, approval_status), users(user_id, username)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q15 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'session_attendance' AND COLUMN_NAME IN ('attendance_id', 'user_id', 'component_id', 'status')) = 4 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'course_component' AND COLUMN_NAME IN ('component_id', 'course_id', 'type')) = 3 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'medical' AND COLUMN_NAME IN ('medical_id', 'attendance_id', 'approval_status')) = 3 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'users' AND COLUMN_NAME IN ('user_id', 'username')) = 2, 'SELECT ''03 scenario 2: attendance exactly 80 % (counting approved medicals)'' AS check_name, IF(x.c > 0, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' student/course(s)'', IFNULL(CONCAT('' (e.g. '', x.s, '')''), '''')) USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM (SELECT sa.user_id, cc.course_id, COUNT(DISTINCT cc.component_id) AS comps,
        SUM(sa.status IN (''present'', ''late'')) AS pres,
        SUM(sa.status = ''absent'' AND md.approval_status = ''approved'') AS med_ok,
        SUM(md.medical_id IS NOT NULL) AS med_any
 FROM session_attendance sa
 JOIN course_component cc ON cc.component_id = sa.component_id
 LEFT JOIN medical md ON md.attendance_id = sa.attendance_id
 GROUP BY sa.user_id, cc.course_id) a JOIN users u ON u.user_id = a.user_id WHERE 100 * (a.pres + a.med_ok) = 80 * (15 * a.comps)) AS c, (SELECT SUBSTRING(GROUP_CONCAT(DISTINCT CONCAT(u.username, '' '', a.course_id) SEPARATOR '', ''), 1, 200) FROM (SELECT sa.user_id, cc.course_id, COUNT(DISTINCT cc.component_id) AS comps,
        SUM(sa.status IN (''present'', ''late'')) AS pres,
        SUM(sa.status = ''absent'' AND md.approval_status = ''approved'') AS med_ok,
        SUM(md.medical_id IS NOT NULL) AS med_any
 FROM session_attendance sa
 JOIN course_component cc ON cc.component_id = sa.component_id
 LEFT JOIN medical md ON md.attendance_id = sa.attendance_id
 GROUP BY sa.user_id, cc.course_id) a JOIN users u ON u.user_id = a.user_id WHERE 100 * (a.pres + a.med_ok) = 80 * (15 * a.comps)) AS s) x', 'SELECT ''03 scenario 2: attendance exactly 80 % (counting approved medicals)'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: session_attendance(attendance_id, user_id, component_id, status), course_component(component_id, course_id, type), medical(medical_id, attendance_id, approval_status), users(user_id, username)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q16 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'session_attendance' AND COLUMN_NAME IN ('attendance_id', 'user_id', 'component_id', 'status')) = 4 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'course_component' AND COLUMN_NAME IN ('component_id', 'course_id', 'type')) = 3 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'medical' AND COLUMN_NAME IN ('medical_id', 'attendance_id', 'approval_status')) = 3 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'users' AND COLUMN_NAME IN ('user_id', 'username')) = 2, 'SELECT ''03 scenario 3: attendance below 80 % and no medical'' AS check_name, IF(x.c > 0, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' student/course(s)'', IFNULL(CONCAT('' (e.g. '', x.s, '')''), '''')) USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM (SELECT sa.user_id, cc.course_id, COUNT(DISTINCT cc.component_id) AS comps,
        SUM(sa.status IN (''present'', ''late'')) AS pres,
        SUM(sa.status = ''absent'' AND md.approval_status = ''approved'') AS med_ok,
        SUM(md.medical_id IS NOT NULL) AS med_any
 FROM session_attendance sa
 JOIN course_component cc ON cc.component_id = sa.component_id
 LEFT JOIN medical md ON md.attendance_id = sa.attendance_id
 GROUP BY sa.user_id, cc.course_id) a JOIN users u ON u.user_id = a.user_id WHERE 100 * a.pres < 80 * (15 * a.comps) AND a.med_any = 0) AS c, (SELECT SUBSTRING(GROUP_CONCAT(DISTINCT CONCAT(u.username, '' '', a.course_id) SEPARATOR '', ''), 1, 200) FROM (SELECT sa.user_id, cc.course_id, COUNT(DISTINCT cc.component_id) AS comps,
        SUM(sa.status IN (''present'', ''late'')) AS pres,
        SUM(sa.status = ''absent'' AND md.approval_status = ''approved'') AS med_ok,
        SUM(md.medical_id IS NOT NULL) AS med_any
 FROM session_attendance sa
 JOIN course_component cc ON cc.component_id = sa.component_id
 LEFT JOIN medical md ON md.attendance_id = sa.attendance_id
 GROUP BY sa.user_id, cc.course_id) a JOIN users u ON u.user_id = a.user_id WHERE 100 * a.pres < 80 * (15 * a.comps) AND a.med_any = 0) AS s) x', 'SELECT ''03 scenario 3: attendance below 80 % and no medical'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: session_attendance(attendance_id, user_id, component_id, status), course_component(component_id, course_id, type), medical(medical_id, attendance_id, approval_status), users(user_id, username)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q17 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'session_attendance' AND COLUMN_NAME IN ('attendance_id', 'user_id', 'component_id', 'status')) = 4 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'course_component' AND COLUMN_NAME IN ('component_id', 'course_id', 'type')) = 3 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'medical' AND COLUMN_NAME IN ('medical_id', 'attendance_id', 'approval_status')) = 3 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'users' AND COLUMN_NAME IN ('user_id', 'username')) = 2, 'SELECT ''03 scenario 4: above 80 % because of approved medicals (medical makes the difference)'' AS check_name, IF(x.c > 0, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' student/course(s)'', IFNULL(CONCAT('' (e.g. '', x.s, '')''), '''')) USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM (SELECT sa.user_id, cc.course_id, COUNT(DISTINCT cc.component_id) AS comps,
        SUM(sa.status IN (''present'', ''late'')) AS pres,
        SUM(sa.status = ''absent'' AND md.approval_status = ''approved'') AS med_ok,
        SUM(md.medical_id IS NOT NULL) AS med_any
 FROM session_attendance sa
 JOIN course_component cc ON cc.component_id = sa.component_id
 LEFT JOIN medical md ON md.attendance_id = sa.attendance_id
 GROUP BY sa.user_id, cc.course_id) a JOIN users u ON u.user_id = a.user_id WHERE 100 * a.pres <= 80 * (15 * a.comps) AND 100 * (a.pres + a.med_ok) > 80 * (15 * a.comps) AND a.med_ok > 0) AS c, (SELECT SUBSTRING(GROUP_CONCAT(DISTINCT CONCAT(u.username, '' '', a.course_id) SEPARATOR '', ''), 1, 200) FROM (SELECT sa.user_id, cc.course_id, COUNT(DISTINCT cc.component_id) AS comps,
