SET @q31 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'marks' AND COLUMN_NAME IN ('student_id', 'course_id', 'isEligible')) = 3 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'session_attendance' AND COLUMN_NAME IN ('user_id', 'component_id')) = 2 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'course_component' AND COLUMN_NAME IN ('component_id', 'course_id')) = 2, 'SELECT ''06 results marked eligible although no attendance is recorded for that course'' AS check_name, IF(x.c = 0, ''PASS'', ''WARN'') AS status, CONVERT(CONCAT(x.c, '' row(s)'', IFNULL(CONCAT('' (e.g. '', x.s, '')''), '''')) USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM marks m WHERE m.isEligible = 1 AND NOT EXISTS (SELECT 1 FROM session_attendance sa JOIN course_component cc ON cc.component_id = sa.component_id WHERE sa.user_id = m.student_id AND cc.course_id = m.course_id)) AS c, (SELECT SUBSTRING(GROUP_CONCAT(DISTINCT CONCAT(m.student_id, ''/'', m.course_id) SEPARATOR '', ''), 1, 200) FROM marks m WHERE m.isEligible = 1 AND NOT EXISTS (SELECT 1 FROM session_attendance sa JOIN course_component cc ON cc.component_id = sa.component_id WHERE sa.user_id = m.student_id AND cc.course_id = m.course_id)) AS s) x', 'SELECT ''06 results marked eligible although no attendance is recorded for that course'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: marks(student_id, course_id, isEligible), session_attendance(user_id, component_id), course_component(component_id, course_id)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q32 := 'SELECT ''07 grade table'' AS check_name, ''WARN'' AS status, CONVERT(''Grade bands used below are the application''''s own (AcademicRules.BANDS = GradingScheme.BANDS). NOT verified against UGC Commission Circular No. 12-2024.'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail';
SET @q33 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'marks' AND COLUMN_NAME IN ('marksid', 'overall_mark', 'grade')) = 3, 'SELECT ''07 grade differs from the grade band of the overall mark'' AS check_name, IF(x.c = 0, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' row(s)'', IFNULL(CONCAT('' (e.g. '', x.s, '')''), '''')) USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM marks m WHERE m.overall_mark IS NOT NULL AND m.grade IS NOT NULL AND m.grade <> CASE WHEN m.overall_mark >= 85 THEN ''A+'' WHEN m.overall_mark >= 75 THEN ''A'' WHEN m.overall_mark >= 70 THEN ''A-'' WHEN m.overall_mark >= 65 THEN ''B+'' WHEN m.overall_mark >= 60 THEN ''B'' WHEN m.overall_mark >= 55 THEN ''B-'' WHEN m.overall_mark >= 50 THEN ''C+'' WHEN m.overall_mark >= 45 THEN ''C'' WHEN m.overall_mark >= 40 THEN ''C-'' WHEN m.overall_mark >= 35 THEN ''D+'' WHEN m.overall_mark >= 30 THEN ''D'' ELSE ''E'' END) AS c, (SELECT SUBSTRING(GROUP_CONCAT(DISTINCT m.marksid SEPARATOR '', ''), 1, 200) FROM marks m WHERE m.overall_mark IS NOT NULL AND m.grade IS NOT NULL AND m.grade <> CASE WHEN m.overall_mark >= 85 THEN ''A+'' WHEN m.overall_mark >= 75 THEN ''A'' WHEN m.overall_mark >= 70 THEN ''A-'' WHEN m.overall_mark >= 65 THEN ''B+'' WHEN m.overall_mark >= 60 THEN ''B'' WHEN m.overall_mark >= 55 THEN ''B-'' WHEN m.overall_mark >= 50 THEN ''C+'' WHEN m.overall_mark >= 45 THEN ''C'' WHEN m.overall_mark >= 40 THEN ''C-'' WHEN m.overall_mark >= 35 THEN ''D+'' WHEN m.overall_mark >= 30 THEN ''D'' ELSE ''E'' END) AS s) x', 'SELECT ''07 grade differs from the grade band of the overall mark'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: marks(marksid, overall_mark, grade)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q34 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'marks' AND COLUMN_NAME IN ('marksid', 'overall_mark', 'grade_points')) = 3, 'SELECT ''07 grade points differ from the band of the overall mark'' AS check_name, IF(x.c = 0, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' row(s)'', IFNULL(CONCAT('' (e.g. '', x.s, '')''), '''')) USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM marks m WHERE m.overall_mark IS NOT NULL AND m.grade_points IS NOT NULL AND m.grade_points <> CASE WHEN m.overall_mark >= 85 THEN 4.0 WHEN m.overall_mark >= 75 THEN 4.0 WHEN m.overall_mark >= 70 THEN 3.7 WHEN m.overall_mark >= 65 THEN 3.3 WHEN m.overall_mark >= 60 THEN 3.0 WHEN m.overall_mark >= 55 THEN 2.7 WHEN m.overall_mark >= 50 THEN 2.3 WHEN m.overall_mark >= 45 THEN 2.0 WHEN m.overall_mark >= 40 THEN 1.7 WHEN m.overall_mark >= 35 THEN 1.3 WHEN m.overall_mark >= 30 THEN 1.0 ELSE 0.0 END) AS c, (SELECT SUBSTRING(GROUP_CONCAT(DISTINCT m.marksid SEPARATOR '', ''), 1, 200) FROM marks m WHERE m.overall_mark IS NOT NULL AND m.grade_points IS NOT NULL AND m.grade_points <> CASE WHEN m.overall_mark >= 85 THEN 4.0 WHEN m.overall_mark >= 75 THEN 4.0 WHEN m.overall_mark >= 70 THEN 3.7 WHEN m.overall_mark >= 65 THEN 3.3 WHEN m.overall_mark >= 60 THEN 3.0 WHEN m.overall_mark >= 55 THEN 2.7 WHEN m.overall_mark >= 50 THEN 2.3 WHEN m.overall_mark >= 45 THEN 2.0 WHEN m.overall_mark >= 40 THEN 1.7 WHEN m.overall_mark >= 35 THEN 1.3 WHEN m.overall_mark >= 30 THEN 1.0 ELSE 0.0 END) AS s) x', 'SELECT ''07 grade points differ from the band of the overall mark'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: marks(marksid, overall_mark, grade_points)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q35 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'marks' AND COLUMN_NAME IN ('marksid', 'published', 'overall_mark', 'grade', 'grade_points')) = 5, 'SELECT ''07 published result without overall mark, grade or grade points'' AS check_name, IF(x.c = 0, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' row(s)'', IFNULL(CONCAT('' (e.g. '', x.s, '')''), '''')) USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM marks m WHERE m.published = 1 AND (m.overall_mark IS NULL OR m.grade IS NULL OR m.grade_points IS NULL)) AS c, (SELECT SUBSTRING(GROUP_CONCAT(DISTINCT m.marksid SEPARATOR '', ''), 1, 200) FROM marks m WHERE m.published = 1 AND (m.overall_mark IS NULL OR m.grade IS NULL OR m.grade_points IS NULL)) AS s) x', 'SELECT ''07 published result without overall mark, grade or grade points'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: marks(marksid, published, overall_mark, grade, grade_points)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q36 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'marks' AND COLUMN_NAME IN ('student_id', 'course_id', 'overall_mark')) = 3 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'component_marks' AND COLUMN_NAME IN ('student_id', 'eval_component_id', 'marks_obtained')) = 3 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'evaluation_component' AND COLUMN_NAME IN ('eval_component_id', 'course_id', 'max_marks', 'weightage')) = 4, 'SELECT ''07 overall mark differs from the weighted component marks (complete sets only)'' AS check_name, IF(x.c = 0, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' row(s)'', IFNULL(CONCAT('' (e.g. '', x.s, '')''), '''')) USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM (SELECT cm.student_id, ec.course_id, ROUND(100 * SUM(cm.marks_obtained / ec.max_marks * ec.weightage) / SUM(ec.weightage), 2) AS calc, COUNT(*) AS n, (SELECT COUNT(*) FROM evaluation_component x WHERE x.course_id = ec.course_id) AS n_comp FROM component_marks cm JOIN evaluation_component ec ON ec.eval_component_id = cm.eval_component_id GROUP BY cm.student_id, ec.course_id) r JOIN marks m ON m.student_id = r.student_id AND m.course_id = r.course_id WHERE r.n = r.n_comp AND m.overall_mark IS NOT NULL AND ABS(m.overall_mark - r.calc) > 0.01) AS c, (SELECT SUBSTRING(GROUP_CONCAT(DISTINCT CONCAT(r.student_id, ''/'', r.course_id) SEPARATOR '', ''), 1, 200) FROM (SELECT cm.student_id, ec.course_id, ROUND(100 * SUM(cm.marks_obtained / ec.max_marks * ec.weightage) / SUM(ec.weightage), 2) AS calc, COUNT(*) AS n, (SELECT COUNT(*) FROM evaluation_component x WHERE x.course_id = ec.course_id) AS n_comp FROM component_marks cm JOIN evaluation_component ec ON ec.eval_component_id = cm.eval_component_id GROUP BY cm.student_id, ec.course_id) r JOIN marks m ON m.student_id = r.student_id AND m.course_id = r.course_id WHERE r.n = r.n_comp AND m.overall_mark IS NOT NULL AND ABS(m.overall_mark - r.calc) > 0.01) AS s) x', 'SELECT ''07 overall mark differs from the weighted component marks (complete sets only)'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: marks(student_id, course_id, overall_mark), component_marks(student_id, eval_component_id, marks_obtained), evaluation_component(eval_component_id, course_id, max_marks, weightage)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q37 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'marks' AND COLUMN_NAME IN ('student_id', 'course_id', 'grade_points', 'published')) = 4 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'courses' AND COLUMN_NAME IN ('course_id', 'credits')) = 2, 'SELECT ''08 CGPA outside 0-4 (published results, GPA = sum(points x credits) / sum(credits))'' AS check_name, IF(x.c = 0, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' row(s)'', IFNULL(CONCAT('' (e.g. '', x.s, '')''), '''')) USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM (SELECT m.student_id, SUM(m.grade_points * c.credits) / SUM(c.credits) AS g FROM marks m JOIN courses c ON c.course_id = m.course_id WHERE m.published = 1 AND m.grade_points IS NOT NULL GROUP BY m.student_id HAVING g < 0 OR g > 4) q) AS c, (SELECT SUBSTRING(GROUP_CONCAT(DISTINCT q.student_id SEPARATOR '', ''), 1, 200) FROM (SELECT m.student_id, SUM(m.grade_points * c.credits) / SUM(c.credits) AS g FROM marks m JOIN courses c ON c.course_id = m.course_id WHERE m.published = 1 AND m.grade_points IS NOT NULL GROUP BY m.student_id HAVING g < 0 OR g > 4) q) AS s) x', 'SELECT ''08 CGPA outside 0-4 (published results, GPA = sum(points x credits) / sum(credits))'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: marks(student_id, course_id, grade_points, published), courses(course_id, credits)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q38 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'marks' AND COLUMN_NAME IN ('published', 'grade_points')) = 2, 'SELECT ''08 published results with grade points (need at least one to compute a GPA)'' AS check_name, IF(x.c > 0, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' result(s)'', IFNULL(CONCAT('' (e.g. '', x.s, '')''), '''')) USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM marks m WHERE m.published = 1 AND m.grade_points IS NOT NULL) AS c, (SELECT SUBSTRING(GROUP_CONCAT(DISTINCT m.marksid SEPARATOR '', ''), 1, 200) FROM marks m WHERE m.published = 1 AND m.grade_points IS NOT NULL) AS s) x', 'SELECT ''08 published results with grade points (need at least one to compute a GPA)'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: marks(published, grade_points)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q39 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'marks' AND COLUMN_NAME IN ('student_id', 'published', 'grade_points')) = 3, 'SELECT ''08 students with a CGPA'' AS check_name, IF(x.c > 0, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' student(s)'', IFNULL(CONCAT('' (e.g. '', x.s, '')''), '''')) USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM (SELECT DISTINCT student_id FROM marks WHERE published = 1 AND grade_points IS NOT NULL) s) AS c, (SELECT SUBSTRING(GROUP_CONCAT(DISTINCT s.student_id SEPARATOR '', ''), 1, 200) FROM (SELECT DISTINCT student_id FROM marks WHERE published = 1 AND grade_points IS NOT NULL) s) AS s) x', 'SELECT ''08 students with a CGPA'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: marks(student_id, published, grade_points)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');

-- one result set: check_name | status (PASS / FAIL / WARN / INFO / SKIP) | detail
SET @sql := CONCAT_WS(' UNION ALL ', @q1, @q2, @q3, @q4, @q5, @q6, @q7, @q8, @q9, @q10, @q11, @q12, @q13, @q14, @q15, @q16, @q17, @q18, @q19, @q20, @q21, @q22, @q23, @q24, @q25, @q26, @q27, @q28, @q29, @q30, @q31, @q32, @q33, @q34, @q35, @q36, @q37, @q38, @q39);
PREPARE st FROM @sql;
EXECUTE st;
DEALLOCATE PREPARE st;

-- ========================== Part 2: reports ==========================

-- Report A - attendance per student and course (theory, practical, combined)
SET @s := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'session_attendance' AND COLUMN_NAME IN ('attendance_id', 'user_id', 'component_id', 'status')) = 4 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'course_component' AND COLUMN_NAME IN ('component_id', 'course_id', 'type')) = 3 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'medical' AND COLUMN_NAME IN ('medical_id', 'attendance_id', 'approval_status')) = 3 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'courses' AND COLUMN_NAME IN ('course_id', 'course_code')) = 2 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'students' AND COLUMN_NAME IN ('user_id', 'registration_no', 'student_status')) = 3 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'users' AND COLUMN_NAME IN ('user_id', 'username')) = 2, 'SELECT u.username, s.registration_no, s.student_status, c.course_code, IF(SUM(cc.type = ''THEORY'') = 0, NULL, ROUND(100 * SUM(cc.type = ''THEORY'' AND (sa.status IN (''present'', ''late'') OR md.approval_status = ''approved'')) / 15, 1)) AS theory_pct, IF(SUM(cc.type = ''PRACTICAL'') = 0, NULL, ROUND(100 * SUM(cc.type = ''PRACTICAL'' AND (sa.status IN (''present'', ''late'') OR md.approval_status = ''approved'')) / 15, 1)) AS practical_pct, ROUND(100 * SUM(sa.status IN (''present'', ''late'') OR md.approval_status = ''approved'') / (15 * COUNT(DISTINCT cc.component_id)), 1) AS combined_pct, ROUND(100 * SUM(sa.status IN (''present'', ''late'')) / (15 * COUNT(DISTINCT cc.component_id)), 1) AS combined_without_medical_pct, SUM(md.approval_status = ''approved'') AS medical_approved, SUM(md.approval_status = ''pending'') AS medical_pending, SUM(md.approval_status = ''rejected'') AS medical_rejected, IF(100 * SUM(sa.status IN (''present'', ''late'') OR md.approval_status = ''approved'') >= 80 * 15 * COUNT(DISTINCT cc.component_id), ''YES'', ''NO'') AS attendance_eligible FROM session_attendance sa JOIN course_component cc ON cc.component_id = sa.component_id JOIN courses c ON c.course_id = cc.course_id JOIN students s ON s.user_id = sa.user_id JOIN users u ON u.user_id = s.user_id LEFT JOIN medical md ON md.attendance_id = sa.attendance_id GROUP BY u.user_id, u.username, s.registration_no, s.student_status, c.course_id, c.course_code ORDER BY c.course_code, u.username', 'SELECT ''Report A - attendance per student and course (theory, practical, combined)'' AS report, ''SKIPPED - missing: session_attendance(attendance_id, user_id, component_id, status), course_component(component_id, course_id, type), medical(medical_id, attendance_id, approval_status), courses(course_id, course_code), students(user_id, registration_no, student_status), users(user_id, username)'' AS detail');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
-- Report B - eligibility per student and course (CA %, attendance %, stored vs recomputed)
SET @s := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'session_attendance' AND COLUMN_NAME IN ('attendance_id', 'user_id', 'component_id', 'status')) = 4 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'course_component' AND COLUMN_NAME IN ('component_id', 'course_id', 'type')) = 3 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'medical' AND COLUMN_NAME IN ('medical_id', 'attendance_id', 'approval_status')) = 3 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'marks' AND COLUMN_NAME IN ('student_id', 'course_id', 'obtainMarks', 'finalMarks', 'overall_mark', 'grade', 'grade_points', 'isEligible', 'published')) = 9 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'courses' AND COLUMN_NAME IN ('course_id', 'course_code')) = 2 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'students' AND COLUMN_NAME IN ('user_id')) = 1 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'users' AND COLUMN_NAME IN ('user_id', 'username')) = 2, 'SELECT u.username, c.course_code, m.obtainMarks AS ca_pct, m.finalMarks AS final_pct, m.overall_mark, m.grade, m.grade_points, IF(a.user_id IS NULL, NULL, ROUND(100 * (a.pres + a.med_ok) / (15 * a.comps), 1)) AS attendance_pct, m.isEligible AS stored_eligible, IF(a.user_id IS NULL, NULL, (m.obtainMarks >= 40 AND 100 * (a.pres + a.med_ok) >= 80 * (15 * a.comps))) AS recomputed_eligible, m.published FROM marks m JOIN courses c ON c.course_id = m.course_id JOIN students s ON s.user_id = m.student_id JOIN users u ON u.user_id = s.user_id LEFT JOIN (SELECT sa.user_id, cc.course_id, COUNT(DISTINCT cc.component_id) AS comps,
        SUM(sa.status IN (''present'', ''late'')) AS pres,
        SUM(sa.status = ''absent'' AND md.approval_status = ''approved'') AS med_ok,
        SUM(md.medical_id IS NOT NULL) AS med_any
 FROM session_attendance sa
 JOIN course_component cc ON cc.component_id = sa.component_id
 LEFT JOIN medical md ON md.attendance_id = sa.attendance_id
 GROUP BY sa.user_id, cc.course_id) a ON a.user_id = m.student_id AND a.course_id = m.course_id ORDER BY c.course_code, u.username', 'SELECT ''Report B - eligibility per student and course (CA %, attendance %, stored vs recomputed)'' AS report, ''SKIPPED - missing: session_attendance(attendance_id, user_id, component_id, status), course_component(component_id, course_id, type), medical(medical_id, attendance_id, approval_status), marks(student_id, course_id, obtainMarks, finalMarks, overall_mark, grade, grade_points, isEligible, published), courses(course_id, course_code), students(user_id), users(user_id, username)'' AS detail');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
-- Report C - SGPA per student and semester (published results)
SET @s := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'marks' AND COLUMN_NAME IN ('student_id', 'course_id', 'grade_points', 'published')) = 4 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'courses' AND COLUMN_NAME IN ('course_id', 'credits', 'academic_level', 'semester')) = 4 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'students' AND COLUMN_NAME IN ('user_id', 'batch', 'student_status')) = 3 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'users' AND COLUMN_NAME IN ('user_id', 'username')) = 2, 'SELECT u.username, s.batch, s.student_status, c.academic_level AS level, c.semester, COUNT(*) AS graded_courses, SUM(c.credits) AS credits, ROUND(SUM(m.grade_points * c.credits) / SUM(c.credits), 2) AS sgpa FROM marks m JOIN courses c ON c.course_id = m.course_id JOIN students s ON s.user_id = m.student_id JOIN users u ON u.user_id = s.user_id WHERE m.published = 1 AND m.grade_points IS NOT NULL GROUP BY u.user_id, u.username, s.batch, s.student_status, c.academic_level, c.semester ORDER BY s.batch, u.username, c.academic_level, c.semester', 'SELECT ''Report C - SGPA per student and semester (published results)'' AS report, ''SKIPPED - missing: marks(student_id, course_id, grade_points, published), courses(course_id, credits, academic_level, semester), students(user_id, batch, student_status), users(user_id, username)'' AS detail');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
-- Report D - CGPA per student (published results)
SET @s := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'marks' AND COLUMN_NAME IN ('student_id', 'course_id', 'grade_points', 'published')) = 4 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'courses' AND COLUMN_NAME IN ('course_id', 'credits')) = 2 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'students' AND COLUMN_NAME IN ('user_id', 'batch', 'student_status')) = 3 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'users' AND COLUMN_NAME IN ('user_id', 'username')) = 2, 'SELECT x.username, x.batch, x.student_status, x.graded_courses, x.credits, x.cgpa FROM (SELECT s.user_id, u.username, s.batch, s.student_status, COUNT(*) AS graded_courses, SUM(c.credits) AS credits, ROUND(SUM(m.grade_points * c.credits) / SUM(c.credits), 2) AS cgpa FROM marks m JOIN courses c ON c.course_id = m.course_id JOIN students s ON s.user_id = m.student_id JOIN users u ON u.user_id = s.user_id WHERE m.published = 1 AND m.grade_points IS NOT NULL GROUP BY s.user_id, u.username, s.batch, s.student_status) x ORDER BY x.batch, x.username', 'SELECT ''Report D - CGPA per student (published results)'' AS report, ''SKIPPED - missing: marks(student_id, course_id, grade_points, published), courses(course_id, credits), students(user_id, batch, student_status), users(user_id, username)'' AS detail');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
-- Report E - batch summary (students with a CGPA, average / lowest / highest CGPA)
SET @s := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'marks' AND COLUMN_NAME IN ('student_id', 'course_id', 'grade_points', 'published')) = 4 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'courses' AND COLUMN_NAME IN ('course_id', 'credits')) = 2 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'students' AND COLUMN_NAME IN ('user_id', 'batch', 'student_status')) = 3 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'users' AND COLUMN_NAME IN ('user_id', 'username')) = 2, 'SELECT x.batch, COUNT(*) AS students_with_cgpa, ROUND(AVG(x.cgpa), 2) AS batch_average_cgpa, MIN(x.cgpa) AS lowest_cgpa, MAX(x.cgpa) AS highest_cgpa FROM (SELECT s.user_id, u.username, s.batch, s.student_status, COUNT(*) AS graded_courses, SUM(c.credits) AS credits, ROUND(SUM(m.grade_points * c.credits) / SUM(c.credits), 2) AS cgpa FROM marks m JOIN courses c ON c.course_id = m.course_id JOIN students s ON s.user_id = m.student_id JOIN users u ON u.user_id = s.user_id WHERE m.published = 1 AND m.grade_points IS NOT NULL GROUP BY s.user_id, u.username, s.batch, s.student_status) x GROUP BY x.batch ORDER BY x.batch', 'SELECT ''Report E - batch summary (students with a CGPA, average / lowest / highest CGPA)'' AS report, ''SKIPPED - missing: marks(student_id, course_id, grade_points, published), courses(course_id, credits), students(user_id, batch, student_status), users(user_id, username)'' AS detail');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
-- Report F - batch eligibility per course
SET @s := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'marks' AND COLUMN_NAME IN ('student_id', 'course_id', 'obtainMarks', 'isEligible')) = 4 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'courses' AND COLUMN_NAME IN ('course_id', 'course_code')) = 2 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'students' AND COLUMN_NAME IN ('user_id', 'batch')) = 2, 'SELECT c.course_code, s.batch, COUNT(*) AS results, SUM(m.isEligible = 1) AS eligible, SUM(m.isEligible = 0) AS not_eligible, SUM(m.obtainMarks < 40) AS ca_below_40 FROM marks m JOIN courses c ON c.course_id = m.course_id JOIN students s ON s.user_id = m.student_id GROUP BY c.course_id, c.course_code, s.batch ORDER BY c.course_code, s.batch', 'SELECT ''Report F - batch eligibility per course'' AS report, ''SKIPPED - missing: marks(student_id, course_id, obtainMarks, isEligible), courses(course_id, course_code), students(user_id, batch)'' AS detail');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;